// recipe: sound-patch-state
// args: none
// returns: ok, found, prefixes, owners, error, detail
//
// Answers whether the recorded-sound instrument is actually installed on the game's own `Sound.Play` overloads. A recorder
// that reports "armed" but has no prefix on the method records nothing, and the two are indistinguishable from the read side
// (measured 2026-11-02: count=0 after a menu click). This asks Harmony directly.
//
// ONE LINE ON PURPOSE: the client's evaluator takes one top-level expression.
((System.Func<string>)(() => { var flags = System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic; var sound = (System.Type)null; var assemblies = System.AppDomain.CurrentDomain.GetAssemblies(); for (var i = 0; i < assemblies.Length; i++) { try { sound = assemblies[i].GetType("Sound", false); } catch { sound = null; } if (sound != null) { break; } } if (sound == null) { return "{\"ok\":false,\"error\":\"no-sound-type\"}"; } var byName = sound.GetMethod("Play", flags, null, new System.Type[] { typeof(string), typeof(UnityEngine.Vector2), typeof(bool), typeof(bool), typeof(UnityEngine.Transform), typeof(float), typeof(float), typeof(bool), typeof(bool) }, null); var byClip = sound.GetMethod("Play", flags, null, new System.Type[] { typeof(UnityEngine.AudioClip), typeof(UnityEngine.Vector2), typeof(bool), typeof(bool), typeof(UnityEngine.Transform), typeof(float), typeof(float), typeof(bool), typeof(bool) }, null); var builder = new System.Text.StringBuilder(); var total = 0; foreach (var method in new System.Reflection.MethodInfo[] { byName, byClip }) { if (method == null) { builder.Append("missing;"); continue; } var info = HarmonyLib.Harmony.GetPatchInfo(method); var count = info == null || info.Prefixes == null ? 0 : info.Prefixes.Count; var owners = new System.Text.StringBuilder(); if (count > 0) { foreach (var patch in info.Prefixes) { owners.Append(patch.owner).Append(','); } } builder.Append(method.GetParameters()[0].ParameterType.Name).Append("=").Append(count).Append("[").Append(owners).Append("];"); total += count; } return "{\"ok\":true,\"found\":true,\"prefixes\":" + total.ToString(System.Globalization.CultureInfo.InvariantCulture) + ",\"owners\":\"" + builder.ToString() + "\"}"; }))()
